/**
 * A listener used when downloading message content.
 *
 * Its shape is loosely based on `nsIStreamListener`, which cannot be used in
 * this instance because we don't always have a request/channel that can be used
 * in method calls when fetching a message's content (and using `nullptr`
 * everywhere is quite ugly and potentially unsafe).
 */
[scriptable, uuid(027150b1-d127-41a9-8945-18f9374755b3)]
interface IExchangeMessageFetchListener : nsISupports
{
  void onFetchStart();
  void onFetchedDataAvailable(in nsIInputStream inputStream);
  void onFetchStop(in nsresult status);
};

// IExchangeMessageFetchListener.onFetchedDataAvailable implementation.
// (analogous to nsIStreamListener.onDataAvailable)
NS_IMETHOD OnFetchedDataAvailable(nsIInputStream* inputStream) override {
  uint64_t bytesCopied;
  MOZ_ASSERT(mOut);
  nsresult rv = SyncCopyStream(inputStream, mOut, bytesCopied);
  NS_ENSURE_SUCCESS(rv, rv);
  mMsgSize += bytesCopied;
  return NS_OK;

// EWS returns the content of the email b64encoded on top of any
// encoding within the message.
let mime_content =
    BASE64_STANDARD
        .decode(raw_mime)
        .map_err(|_| XpComEwsError::Processing {
            message: "MIME content for item is not validly base64 encoded".to_string(),
        })?;

Ok(self.listener.on_fetched_data_available(mime_content)?)
